async function logAudit(admin, action, report, details) {
  if (!admin) return;
  try {
    const c = await sb();
    await c.from('report_audit_log').insert({
      report_id: report?.id || null,
      report_number: report?.report_number || null,
      report_client_name: report?.client_name || null,
      admin_id: admin.id,
      admin_name: admin.admin_name,
      action,
      details: details || null,
    });
  } catch(e) { console.error('audit log failed', e); }
}

  const LOGO = '';

// ── PDF GENERATION ─────────────────────────────────────────────────
async function generateReportPDF(report) {
  const JsPDF = await loadJsPDF();
  const doc = new JsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const W = 210, M = 14, CW = W - M*2;

  // HEADER
  try { doc.addImage('data:image/jpeg;base64,'+LOGO, 'JPEG', 148, 7, 48, 20); } catch(e) {}
  doc.setTextColor(120,120,120); doc.setFontSize(8); doc.setFont('helvetica','normal');
  doc.text('N° RAPPORTO', M, 13);
  doc.setTextColor(20,20,20); doc.setFontSize(20); doc.setFont('helvetica','bold');
  doc.text(report.report_number||'--', M, 23);
  doc.setDrawColor(200,200,200); doc.setLineWidth(0.3); doc.line(M, 30, W-M, 30);

  // TITOLO
  doc.setTextColor(20,20,20); doc.setFontSize(13); doc.setFont('helvetica','bold');
  doc.text('RAPPORTO DI SERVIZIO', M, 39);

  let y = 43;
  const agenti = Array.isArray(report.agents_json) ? report.agents_json.map(a=>a.name).join(' – ') : (report.submitted_by_name||'--');

  const drawBox = (yy, h) => { doc.setDrawColor(60,60,60); doc.setLineWidth(0.4); doc.roundedRect(M, yy, CW, h, 2.5, 2.5, 'S'); };
  const sepLine = (yy) => { doc.setDrawColor(210,210,210); doc.setLineWidth(0.2); doc.line(M+3, yy, W-M-3, yy); };
  const fieldRow = (label, value, x, yy, maxW) => {
    doc.setTextColor(90,90,90); doc.setFontSize(8.5); doc.setFont('helvetica','bold');
    doc.text(label+':', x, yy);
    const lw = doc.getTextWidth(label+': ')+1;
    doc.setTextColor(15,15,15); doc.setFontSize(10.5); doc.setFont('helvetica','normal');
    doc.text(String(value||'--'), x+lw, yy, {maxWidth: maxW-lw});
    doc.setDrawColor(195,195,195); doc.setLineWidth(0.15);
    doc.line(x+lw, yy+1, x+maxW, yy+1);
  };

  // BOX DATA (h=14)
  drawBox(y, 14);
  fieldRow('Data', fromISO(report.service_date), M+4, y+9, CW-8);
  y += 19;

  // BOX AGENTE/CLIENTE/LUOGO/INDIRIZZO (h=48)
  drawBox(y, 48);
  fieldRow('Agente', agenti, M+4, y+10, CW-8); sepLine(y+14);
  fieldRow('Cliente', report.client_name||'--', M+4, y+22, CW-8); sepLine(y+26);
  fieldRow('Luogo', report.location||'--', M+4, y+36, CW/2-6);
  fieldRow('Indirizzo', report.address||'--', M+CW/2+2, y+36, CW/2-6);
  y += 53;

  // BOX ORARIO (h=14)
  drawBox(y, 14);
  doc.setTextColor(90,90,90); doc.setFontSize(8.5); doc.setFont('helvetica','bold'); doc.text('Orario:', M+4, y+9);
  fieldRow('Inizio', report.start_time||'--', M+24, y+9, 46);
  fieldRow('Fine', report.end_time||'--', M+24+54, y+9, 46);
  y += 19;

  // BOX PAUSA (h=24 se presente, 14 altrimenti)
  if(report.has_break){
    drawBox(y, 24);
    doc.setTextColor(90,90,90); doc.setFontSize(8.5); doc.setFont('helvetica','bold'); doc.text('Pausa:', M+4, y+9);
    fieldRow('Coperta da', report.break_covered_by||'--', M+20, y+9, 80);
    fieldRow('Inizio', report.break_start||'--', M+20, y+19, 40);
    fieldRow('Fine', report.break_end||'--', M+20+48, y+19, 40);
    y += 29;
  } else {
    drawBox(y, 14);
    doc.setTextColor(90,90,90); doc.setFontSize(8.5); doc.setFont('helvetica','bold'); doc.text('Pausa:', M+4, y+9);
    doc.setTextColor(175,175,175); doc.setFontSize(9.5); doc.setFont('helvetica','normal'); doc.text('Nessuna pausa effettuata', M+20, y+9);
    y += 19;
  }

  // BOX OSSERVAZIONI — riempie lo spazio restante fino alle firme
  const sigY = 230;
  const obsH = sigY - y - 5;
  drawBox(y, obsH);
  doc.setTextColor(90,90,90); doc.setFontSize(8.5); doc.setFont('helvetica','bold'); doc.text('Osservazioni:', M+4, y+9);
  if(report.notes){
    doc.setTextColor(15,15,15); doc.setFontSize(10); doc.setFont('helvetica','normal');
    doc.text(doc.splitTextToSize(report.notes, CW-8), M+4, y+18);
  }
  const nLines = Math.floor((obsH-10)/8);
  for(let i=1;i<=nLines;i++){ doc.setDrawColor(210,210,210); doc.setLineWidth(0.15); doc.line(M+4, y+9+i*8, W-M-4, y+9+i*8); }
  y = sigY;

  // FIRME
  const fw = (CW-6)/2;
  const [agentSigData, clientSigData] = await Promise.all([
    report.agent_signature ? urlToDataUrl(report.agent_signature).catch(e => { console.error('agent signature fetch failed', e); return null; }) : null,
    (!report.client_unavailable && report.client_signature) ? urlToDataUrl(report.client_signature).catch(e => { console.error('client signature fetch failed', e); return null; }) : null,
  ]);
  // Agente
  doc.setTextColor(60,60,60); doc.setFontSize(8.5); doc.setFont('helvetica','bold'); doc.text('Firma Agente', M, y+5);
  doc.setDrawColor(150,150,150); doc.setLineWidth(0.3); doc.roundedRect(M, y+7, fw, 28, 2, 2, 'S');
  if(agentSigData){ try{ doc.addImage(agentSigData,'PNG',M+1,y+8,fw-2,26); }catch(e){} }

  // Cliente
  const cx = M+fw+6;
  doc.setTextColor(60,60,60); doc.setFontSize(8.5); doc.setFont('helvetica','bold'); doc.text('Firma Cliente', cx, y+5);
  if(report.client_unavailable){
    doc.setFillColor(250,238,218); doc.roundedRect(cx,y+7,fw,28,2,2,'F');
    doc.setDrawColor(200,150,50); doc.setLineWidth(0.3); doc.roundedRect(cx,y+7,fw,28,2,2,'S');
    doc.setTextColor(122,80,0); doc.setFontSize(9); doc.setFont('helvetica','bold');
    doc.text('Firma non raccolta', cx+fw/2, y+18, {align:'center'});
    doc.setFont('helvetica','normal'); doc.setFontSize(7.5);
    doc.text('Responsabile assente al termine del servizio', cx+fw/2, y+26, {align:'center', maxWidth:fw-4});
  } else {
    if(report.client_signer_name){ doc.setTextColor(20,20,20); doc.setFontSize(8.5); doc.setFont('helvetica','bold'); doc.text(report.client_signer_name, cx+fw, y+5, {align:'right'}); }
    doc.setDrawColor(150,150,150); doc.setLineWidth(0.3); doc.roundedRect(cx,y+7,fw,28,2,2,'S');
    if(clientSigData){ try{ doc.addImage(clientSigData,'PNG',cx+1,y+8,fw-2,26); }catch(e){} }
    doc.setTextColor(130,130,130); doc.setFontSize(6.5); doc.setFont('helvetica','italic');
    doc.text("Con la firma si conferma l'impiego svolto e l'esattezza dei dati", cx+fw, y+38, {align:'right', maxWidth:fw});
  }

  // FOOTER
  doc.setDrawColor(200,200,200); doc.setLineWidth(0.3); doc.line(M, 282, W-M, 282);
  doc.setTextColor(110,110,110); doc.setFontSize(7); doc.setFont('helvetica','normal');
  doc.text('DELTAgroup Security Services AG  ·  Filiale Ticino  ·  Via alla Foce 4, CH-6933 Muzzano  ·  T +41 91 921 49 49  ·  ticino@delta.ch  ·  www.delta.ch', W/2, 287, {align:'center'});

  return doc;
}

