function MonthHeader({ label, count }) {
  return (
    <div style={{
      position:'sticky', top:0, zIndex:1,
      padding:'8px 14px',
      background:T.c.bg,
      borderBottom:`1px solid ${T.c.border}`,
      fontSize:T.f.xs-1, color:T.c.textMuted, fontWeight:600,
      letterSpacing:0.6, textTransform:'uppercase',
      display:'flex', justifyContent:'space-between', alignItems:'center', gap:8,
    }}>
      <span>{label}</span>
      <span style={{color:T.c.textFaint,fontWeight:500,letterSpacing:0}}>{count} {count===1?'giorno':'giorni'}</span>
    </div>
  );
}

function CountChip({ value, color, bg, border, title }) {
  if (!value) return null;
  return (
    <span title={title} style={{
      display:'inline-flex', alignItems:'center', justifyContent:'center',
      minWidth:20, padding:'2px 6px',
      fontSize:T.f.xs-1, fontWeight:600,
      color, background:bg, border:`1px solid ${border}`,
      borderRadius:T.r.sm, lineHeight:1.2,
    }}>{value}</span>
  );
}

function DayRow({ date, stats, isSelected, isToday, onClick }) {
  const d = new Date(date+'T12:00:00');
  const [hover, setHover] = useState(false);
  const bg = isSelected ? T.c.greenLight : (hover ? T.c.greenSoft : T.c.surface);
  return (
    <div onClick={onClick} onMouseEnter={()=>setHover(true)} onMouseLeave={()=>setHover(false)} style={{padding:'12px 14px',cursor:'pointer',borderBottom:`1px solid ${T.c.border}`,background:bg,display:'flex',alignItems:'center',gap:12,transition:'background 0.1s',position:'relative'}}>
      {isSelected && <span style={{position:'absolute',left:0,top:0,bottom:0,width:3,background:T.c.green}} />}
      <div style={{textAlign:'center',minWidth:38}}>
        <div style={{fontSize:T.f.h+4,fontWeight:600,lineHeight:1,color:isSelected?T.c.green:T.c.text}}>{d.getDate()}</div>
        <div style={{fontSize:T.f.xs-1,color:T.c.textFaint,marginTop:3,textTransform:'uppercase',letterSpacing:0.5}}>{DAYS_SHORT[d.getDay()]}</div>
      </div>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontSize:T.f.md,fontWeight:isToday?600:500,color:T.c.text}}>
          {isToday ? 'Oggi' : `${DAYS_SHORT[d.getDay()]} ${d.getDate()} ${MONTHS_SHORT[d.getMonth()]}`}
          {stats.late>0 && <span style={{marginLeft:8,fontSize:T.f.xs-1,background:T.c.warningBg,color:T.c.warningText,padding:'1px 6px',borderRadius:3,border:`1px solid ${T.c.warningBorder}`,fontWeight:500}}>+{stats.late} ritardo</span>}
        </div>
        <div style={{fontSize:T.f.xs,color:T.c.textMuted,marginTop:3,display:'flex',alignItems:'center',gap:5,flexWrap:'wrap'}}>
          <span>{stats.total} {stats.total===1?'rapporto':'rapporti'}</span>
          <CountChip value={stats.submitted} color={T.c.dangerText} bg={T.c.dangerBg} border={T.c.dangerBorder} title="Da leggere" />
          <CountChip value={stats.read} color={T.c.warningText} bg={T.c.warningBg} border={T.c.warningBorder} title="Da inviare" />
          <CountChip value={stats.sent} color="#1a5c1a" bg={T.c.greenLight} border="#cfe5b8" title="Inviati" />
        </div>
      </div>
    </div>
  );
}

function ReportRow({ report, isSelected, onClick }) {
  const [hover, setHover] = useState(false);
  const isUnread = report.status === 'submitted';
  const isSent = report.status === 'sent_to_client';
  const accent = isSent ? T.c.green : report.status==='read' ? T.c.warning : T.c.danger;
  const bg = isSelected
    ? T.c.greenLight
    : isUnread
      ? (hover ? '#fde7e7' : '#fef6f6')
      : (hover ? T.c.surfaceHover : T.c.surface);
  return (
    <div onClick={onClick} onMouseEnter={()=>setHover(true)} onMouseLeave={()=>setHover(false)} style={{padding:'12px 14px',cursor:'pointer',borderBottom:`1px solid ${T.c.border}`,borderLeft:`3px solid ${accent}`,background:bg,transition:'background 0.1s',opacity:isSent?0.78:1,position:'relative'}}>
      {isUnread && <span style={{position:'absolute',top:14,right:14,width:8,height:8,borderRadius:'50%',background:T.c.danger,boxShadow:`0 0 0 3px ${T.c.dangerBg}`}} title="Da leggere" />}
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:4,gap:10}}>
        <div style={{fontWeight:isUnread?600:500,fontSize:T.f.md,minWidth:0,color:isUnread?T.c.dangerText:T.c.text,paddingRight:isUnread?16:0}}>{report.submitted_by_name}</div>
        {!isUnread && <StatusBadge status={report.status} />}
      </div>
      <div style={{fontSize:T.f.sm,color:T.c.textMuted,marginBottom:6,fontWeight:isUnread?500:400}}>{report.client_name} · {report.address}</div>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:6}}>
        <TypeBadge type={report.report_type} />
        <div style={{fontSize:T.f.xs-1,color:T.c.textFaint}}>{fmtTime(report.submitted_at)}</div>
      </div>
      {report.is_late && <div style={{fontSize:T.f.xs-1,color:T.c.warningText,background:T.c.warningBg,padding:'2px 7px',borderRadius:4,marginTop:6,display:'inline-block',border:`1px solid ${T.c.warningBorder}`}}>Ricevuto in ritardo</div>}
    </div>
  );
}

function InboxTab({ currentAdmin }) {
  const confirmModal = useConfirm();
  const toast = useToast();
  const [days, setDays] = useState([]);
  const [selectedDay, setSelectedDay] = useState(null);
  const [dayReports, setDayReports] = useState([]);
  const [selectedReport, setSelectedReport] = useState(null);
  const [loading, setLoading] = useState(true);
  const [loadingDay, setLoadingDay] = useState(false);
  const [searchDate, setSearchDate] = useState('');
  const [editMode, setEditMode] = useState(false);
  const [editForm, setEditForm] = useState({});
  const [saving, setSaving] = useState(false);
  const [revisions, setRevisions] = useState([]);
  const [clientsMap, setClientsMap] = useState({});
  const [sendingId, setSendingId] = useState(null);

  const loadDays = useCallback(async () => {
    setLoading(true);
    const c = await sb();
    const oneYearAgo = new Date(); oneYearAgo.setFullYear(oneYearAgo.getFullYear()-1);
    const { data } = await c.from('dr_reports').select('id,service_date,status,is_late,report_type,submitted_at').gte('service_date', oneYearAgo.toISOString().split('T')[0]).is('deleted_at', null).order('service_date',{ascending:false});
    if (data) {
      const grouped = {};
      data.forEach(r => {
        if (!grouped[r.service_date]) grouped[r.service_date] = {total:0,submitted:0,read:0,sent:0,late:0};
        grouped[r.service_date].total++;
        if (r.status==='submitted') grouped[r.service_date].submitted++;
        if (r.status==='read') grouped[r.service_date].read++;
        if (r.status==='sent_to_client') grouped[r.service_date].sent++;
        if (r.is_late) grouped[r.service_date].late++;
      });
      setDays(Object.entries(grouped).sort((a,b) => b[0].localeCompare(a[0])));
    }
    setLoading(false);
  }, []);

  useEffect(() => { loadDays(); }, []);

  useEffect(() => {
    sb().then(c => c.from('report_clients').select('name,email')).then(({data}) => {
      if (data) { const m = {}; data.forEach(cl => { m[cl.name.toLowerCase()] = cl.email; }); setClientsMap(m); }
    });
  }, []);

  const loadDay = async (date) => {
    setSelectedDay(date); setSelectedReport(null); setEditMode(false); setLoadingDay(true);
    const c = await sb();
    const { data } = await c.from('dr_reports').select('*').eq('service_date', date).is('deleted_at', null).order('submitted_at',{ascending:false});
    if (data) {
      setDayReports(data);
      const toRead = data.filter(r => r.status==='submitted').map(r => r.id);
      if (toRead.length > 0) {
        await c.from('dr_reports').update({status:'read'}).in('id', toRead);
        setDayReports(prev => prev.map(r => toRead.includes(r.id) ? {...r,status:'read'} : r));
        loadDays();
      }
    }
    setLoadingDay(false);
  };

  const openReport = async (report) => {
    setSelectedReport(report);
    setEditForm({client_name:report.client_name,location:report.location,address:report.address,start_time:report.start_time,end_time:report.end_time,has_break:report.has_break,break_covered_by:report.break_covered_by,break_start:report.break_start,break_end:report.break_end,notes:report.notes});
    setEditMode(false);
    const c = await sb();
    const { data } = await c.from('report_revisions').select('*').eq('report_id', report.id).order('changed_at',{ascending:false});
    if (data) setRevisions(data);
  };

  const saveEdit = async () => {
    setSaving(true);
    const c = await sb();
    const labels = {client_name:'Cliente',location:'Luogo',address:'Indirizzo',start_time:'Inizio',end_time:'Fine',has_break:'Pausa',break_covered_by:'Pausa coperta da',break_start:'Inizio pausa',break_end:'Fine pausa',notes:'Osservazioni'};
    const adminName = currentAdmin?.admin_name || 'Admin';
    const changes = [];
    Object.keys(labels).forEach(k => {
      if (String(editForm[k]??'') !== String(selectedReport[k]??''))
        changes.push({report_id:selectedReport.id,field_name:labels[k],old_value:String(selectedReport[k]??''),new_value:String(editForm[k]??''),changed_by:adminName});
    });
    await c.from('dr_reports').update({...editForm,updated_at:new Date().toISOString()}).eq('id',selectedReport.id);
    if (changes.length > 0) {
      await c.from('report_revisions').insert(changes);
      await logAudit(currentAdmin, 'edit', selectedReport, { fields: changes.map(ch => ({ field: ch.field_name, old: ch.old_value, new: ch.new_value })) });
    }
    const updated = {...selectedReport,...editForm};
    setSelectedReport(updated);
    setDayReports(prev => prev.map(r => r.id===updated.id ? updated : r));
    if (changes.length > 0) setRevisions(prev => [...changes.map(ch=>({...ch,changed_at:new Date().toISOString()})), ...prev]);
    setEditMode(false); setSaving(false);
  };

  const sendToClient = async (report) => {
    setSendingId(report.id);
    try {
      const doc = await generateReportPDF(report);
      const blob = doc.output('blob');
      const file = new File([blob], `Rapporto_${report.report_number}.pdf`, {type:'application/pdf'});
      const email = clientsMap[(report.client_name||'').toLowerCase()] || '';
      const subject = encodeURIComponent(`Rapporto di Servizio ${report.report_number} – ${report.client_name}`);
      const body = encodeURIComponent(`Spettabile Cliente,\n\nin allegato trasmettiamo il Rapporto di Servizio N\u00B0 ${report.report_number} del ${fromISO(report.service_date)}.\n\nCordiali saluti,\nDELTAgroup Security & Services AG`);
      let shareAborted = false;
      if (navigator.canShare && navigator.canShare({files:[file]})) {
        try {
          await navigator.share({files:[file], title:`Rapporto ${report.report_number}`});
        } catch(err) {
          if (err && err.name === 'AbortError') shareAborted = true;
          else throw err;
        }
      } else {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href=url; a.download=file.name; a.click();
        window.open(`mailto:${email}?subject=${subject}&body=${body}`);
      }
      if (shareAborted) { setSendingId(null); return; }
      const confirmed = await confirmModal({
        title: 'Conferma invio al cliente',
        message: `Hai effettivamente inviato il rapporto N° ${report.report_number} a ${report.client_name||'cliente'}?\n\nConferma SOLO se l'email è stata spedita al cliente.\nIn caso contrario il rapporto resterà come "Da inviare".`,
        confirmLabel: 'Sì, segna come inviato',
        cancelLabel: 'No, riprovo dopo',
        tone: 'info',
      });
      if (!confirmed) { setSendingId(null); return; }
      const c = await sb();
      const sentAt = new Date().toISOString();
      await c.from('dr_reports').update({status:'sent_to_client',sent_to_client_at:sentAt}).eq('id',report.id);
      await logAudit(currentAdmin, 'send', report, { recipient: email || null });
      setSelectedReport(r => ({...r,status:'sent_to_client',sent_to_client_at:sentAt}));
      setDayReports(prev => prev.map(r => r.id===report.id ? {...r,status:'sent_to_client',sent_to_client_at:sentAt} : r));
      loadDays();
      toast.success(`Rapporto ${report.report_number} segnato come inviato.`);
    } catch(e) { console.error(e); toast.error('Errore durante la preparazione del PDF.'); }
    setSendingId(null);
  };

  const previewPDF = async (report) => {
    const doc = await generateReportPDF(report);
    const blob = doc.output('blob');
    window.open(URL.createObjectURL(blob), '_blank');
  };

  const deleteReport = async (report) => {
    const isSuper = !!currentAdmin?.is_super;
    const intro = isSuper
      ? `Il rapporto verrà nascosto da Inbox/Spedisci e sarà visibile solo nella sezione Cestino. Potrai ripristinarlo o eliminarlo definitivamente in seguito.`
      : `Il rapporto verrà nascosto da Inbox/Spedisci. Solo un super-admin potrà ripristinarlo o eliminarlo definitivamente.`;
    const ok = await confirmModal({
      title: `Spostare nel cestino il rapporto ${report.report_number}?`,
      message: `${intro}\n\nCliente: ${report.client_name||'—'} · Data: ${fromISO(report.service_date)}`,
      confirmLabel: 'Sposta nel cestino',
      tone: 'warning',
    });
    if (!ok) return;
    try {
      const c = await sb();
      const { error } = await c.rpc('soft_delete_report', { p_token: currentAdmin.token, p_report_id: report.id });
      if (error) throw error;
      await logAudit(currentAdmin, 'delete', report, { soft: true, service_date: report.service_date, submitted_by: report.submitted_by_name });
      setDayReports(prev => prev.filter(r => r.id !== report.id));
      setSelectedReport(null);
      setEditMode(false);
      loadDays();
      toast.success(`Rapporto ${report.report_number} spostato nel cestino.`);
    } catch(e) { console.error(e); toast.error('Errore durante l’eliminazione. Riprova.'); }
  };

  const dayStatus = (d) => { if(d.submitted>0) return 'error'; if(d.read>0) return 'warning'; return 'ok'; };

  const filteredDays = searchDate ? days.filter(([date]) => date.includes(searchDate)) : days;

  return (
    <div style={{display:'flex',height:'100vh',overflow:'hidden'}}>

      {/* Colonna 1: giorni */}
      <div style={{width:280,borderRight:'1px solid #e8e8e8',display:'flex',flexDirection:'column',background:'#fafafa',flexShrink:0}}>
        <div style={{padding:'14px 14px 10px',borderBottom:'1px solid #e8e8e8'}}>
          <div style={{fontWeight:600,fontSize:T.f.lg,marginBottom:12,display:'flex',alignItems:'center',gap:8,color:T.c.text}}><I.inbox size={18} /> Inbox</div>
          <input type="date" value={searchDate} onChange={e=>setSearchDate(e.target.value)} style={{width:'100%',padding:'8px 10px',border:'1px solid #ddd',borderRadius:7,fontSize:13,boxSizing:'border-box',fontFamily:'inherit'}} />
        </div>
        <div style={{flex:1,overflowY:'auto'}}>
          {loading && <div style={{padding:20,textAlign:'center',color:'#888',fontSize:13}}>Caricamento…</div>}
          {(() => {
            const out = [];
            let lastKey = null;
            // first pass: count days per month
            const monthCounts = {};
            filteredDays.forEach(([d]) => {
              const dt = new Date(d+'T12:00:00');
              const k = `${dt.getFullYear()}-${dt.getMonth()}`;
              monthCounts[k] = (monthCounts[k]||0) + 1;
            });
            filteredDays.forEach(([date, stats]) => {
              const dt = new Date(date+'T12:00:00');
              const k = `${dt.getFullYear()}-${dt.getMonth()}`;
              if (k !== lastKey) {
                lastKey = k;
                out.push(<MonthHeader key={'h-'+k} label={`${MONTHS_LONG[dt.getMonth()]} ${dt.getFullYear()}`} count={monthCounts[k]} />);
              }
              out.push(<DayRow key={date} date={date} stats={stats} isSelected={selectedDay===date} isToday={date===todayISO()} onClick={() => loadDay(date)} />);
            });
            return out;
          })()}
          {!loading && filteredDays.length===0 && <div style={{padding:30,textAlign:'center',color:T.c.textFaint,fontSize:T.f.md}}>Nessun dato</div>}
        </div>
      </div>

      {/* Colonna 2: rapporti del giorno */}
      <div style={{width:320,borderRight:'1px solid #e8e8e8',display:'flex',flexDirection:'column',background:'#fff',flexShrink:0}}>
        {!selectedDay
          ? <div style={{flex:1,display:'flex',alignItems:'center',justifyContent:'center',color:T.c.textFaint,fontSize:T.f.md}}><div style={{textAlign:'center'}}><div style={{color:T.c.borderHover,marginBottom:12,display:'flex',justifyContent:'center'}}><I.clock size={36} /></div>Seleziona un giorno</div></div>
          : <>
            <div style={{padding:'14px',borderBottom:`1px solid ${T.c.border}`}}>
              <div style={{fontWeight:600,fontSize:T.f.lg,color:T.c.text}}>{fromISO(selectedDay)}</div>
              <div style={{fontSize:T.f.xs,color:T.c.textMuted,marginTop:5,display:'flex',alignItems:'center',gap:5,flexWrap:'wrap'}}>
                <span>{dayReports.length} {dayReports.length===1?'rapporto':'rapporti'}</span>
                <CountChip value={dayReports.filter(r=>r.status==='submitted').length} color={T.c.dangerText} bg={T.c.dangerBg} border={T.c.dangerBorder} title="Da leggere" />
                <CountChip value={dayReports.filter(r=>r.status==='read').length} color={T.c.warningText} bg={T.c.warningBg} border={T.c.warningBorder} title="Da inviare" />
                <CountChip value={dayReports.filter(r=>r.status==='sent_to_client').length} color="#1a5c1a" bg={T.c.greenLight} border="#cfe5b8" title="Inviati" />
              </div>
            </div>
            <div style={{flex:1,overflowY:'auto'}}>
              {loadingDay && <div style={{padding:20,textAlign:'center',color:'#888',fontSize:13}}>Caricamento…</div>}
              {dayReports.map(r => (
                <ReportRow key={r.id} report={r} isSelected={selectedReport?.id===r.id} onClick={() => openReport(r)} />
              ))}            </div>
          </>
        }
      </div>

      {/* Colonna 3: dettaglio rapporto */}
      <div style={{flex:1,display:'flex',flexDirection:'column',background:'#fff',overflowY:'auto'}}>
        {!selectedReport
          ? <div style={{flex:1,display:'flex',alignItems:'center',justifyContent:'center',color:T.c.textFaint,fontSize:T.f.md}}><div style={{textAlign:'center'}}><div style={{color:T.c.borderHover,marginBottom:12,display:'flex',justifyContent:'center'}}><I.fileText size={36} /></div>Seleziona un rapporto</div></div>
          : <div style={{padding:24,maxWidth:700}}>
            {/* Header */}
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:20,gap:12}}>
              <div>
                <div style={{fontSize:18,fontWeight:600}}>{selectedReport.report_number}</div>
                <div style={{fontSize:13,color:'#888',marginTop:2}}>Ricevuto {fmtDT(selectedReport.submitted_at)} \u00B7 da {selectedReport.submitted_by_name}</div>
                {selectedReport.is_late && <span style={{fontSize:11,color:'#854f0b',background:'#faeeda',padding:'2px 8px',borderRadius:5,marginTop:4,display:'inline-block'}}>Ricevuto in ritardo rispetto alla data servizio</span>}
              </div>
              <div style={{display:'flex',gap:8,alignItems:'center',flexShrink:0}}>
                <StatusBadge status={selectedReport.status} />
                <TypeBadge type={selectedReport.report_type} />
              </div>
            </div>

            {/* Dati rapporto */}
            <div style={{background:'#fafafa',borderRadius:12,padding:20,marginBottom:16,border:'1px solid #e8e8e8'}}>
              {!editMode ? (
                <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'10px 24px'}}>
                  {[
                    ['Data servizio', fromISO(selectedReport.service_date)],
                    ['Agenti', Array.isArray(selectedReport.agents_json) ? selectedReport.agents_json.map(a=>a.name).join(', ') : selectedReport.submitted_by_name],
                    ['Cliente', selectedReport.client_name, true],
                    ['Luogo', selectedReport.location],
                    ['Indirizzo', selectedReport.address, true],
                    ['Inizio', selectedReport.start_time||'—'],
                    ['Fine', selectedReport.end_time||'—'],
                    selectedReport.has_break && ['Pausa', `${selectedReport.break_start}–${selectedReport.break_end} (${selectedReport.break_covered_by})`],
                    selectedReport.notes && ['Osservazioni', selectedReport.notes, true],
                  ].filter(Boolean).map(([label,value,full]) => (
                    <div key={label} style={{gridColumn:full?'1/-1':'auto'}}>
                      <div style={{fontSize:10,color:'#999',marginBottom:2}}>{label}</div>
                      <div style={{fontSize:14,color:label==='Fine'&&!selectedReport.end_time?'#e24b4a':'#111'}}>{value}</div>
                    </div>
                  ))}
                  {!selectedReport.end_time && (
                    <div style={{gridColumn:'1/-1',padding:'8px 12px',background:'#fcebeb',borderRadius:7,display:'flex',alignItems:'center',gap:6,marginTop:4}}>
                      <span style={{color:'#a32d2d',fontSize:14}}>⚠️</span>
                      <span style={{fontSize:12,color:'#a32d2d'}}>Orario di fine mancante — correggere prima di inviare al cliente</span>
                    </div>
                  )}
                </div>
              ) : (
                <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:'0 16px'}}>
                  {[
                    ['Cliente','client_name','text',true],
                    ['Luogo','location','text',false],
                    ['Indirizzo','address','text',true],
                    ['Inizio','start_time','time',false],
                    ['Fine','end_time','time',false],
                  ].map(([label,key,type,full]) => (
                    <div key={key} style={{gridColumn:full?'1/-1':'auto',marginBottom:12}}>
                      <div style={{fontSize:11,color:'#888',marginBottom:3}}>{label}</div>
                      <input type={type} value={editForm[key]||''} onChange={e=>setEditForm(f=>({...f,[key]:e.target.value}))} style={{width:'100%',padding:'8px 10px',border:'1px solid #ddd',borderRadius:7,fontSize:13,boxSizing:'border-box',fontFamily:'inherit'}} />
                    </div>
                  ))}
                  <div style={{gridColumn:'1/-1',marginBottom:12}}>
                    <label style={{display:'flex',alignItems:'center',gap:8,cursor:'pointer',marginBottom:8}}>
                      <input type="checkbox" checked={editForm.has_break||false} onChange={e=>setEditForm(f=>({...f,has_break:e.target.checked}))} style={{accentColor:GREEN}} />
                      <span style={{fontSize:13}}>Pausa effettuata</span>
                    </label>
                    {editForm.has_break && (
                      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 1fr',gap:'0 12px'}}>
                        {[['Coperta da','break_covered_by','text'],['Inizio pausa','break_start','time'],['Fine pausa','break_end','time']].map(([label,key,type]) => (
                          <div key={key}><div style={{fontSize:11,color:'#888',marginBottom:3}}>{label}</div><input type={type} value={editForm[key]||''} onChange={e=>setEditForm(f=>({...f,[key]:e.target.value}))} style={{width:'100%',padding:'8px 10px',border:'1px solid #ddd',borderRadius:7,fontSize:13,boxSizing:'border-box',fontFamily:'inherit'}} /></div>
                        ))}
                      </div>
                    )}
                  </div>
                  <div style={{gridColumn:'1/-1',marginBottom:12}}>
                    <div style={{fontSize:11,color:'#888',marginBottom:3}}>Osservazioni</div>
                    <textarea value={editForm.notes||''} onChange={e=>setEditForm(f=>({...f,notes:e.target.value}))} style={{width:'100%',height:80,padding:'8px 10px',border:'1px solid #ddd',borderRadius:7,fontSize:13,resize:'none',fontFamily:'inherit',boxSizing:'border-box'}} />
                  </div>
                </div>
              )}
            </div>

            {/* Firme */}
            {(selectedReport.agent_signature||selectedReport.client_signature) && (
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12,marginBottom:16}}>
                {selectedReport.agent_signature && (
                  <div style={{background:'#fafafa',borderRadius:10,padding:14,border:'1px solid #e8e8e8'}}>
                    <div style={{fontSize:11,color:'#888',marginBottom:8}}>FIRMA AGENTE</div>
                    <img src={selectedReport.agent_signature} style={{width:'100%',height:70,objectFit:'contain',border:'0.5px solid #eee',borderRadius:6}} />
                  </div>
                )}
                {selectedReport.client_signature && (
                  <div style={{background:'#fafafa',borderRadius:10,padding:14,border:'1px solid #e8e8e8'}}>
                    <div style={{fontSize:11,color:'#888',marginBottom:4}}>FIRMA CLIENTE</div>
                    {selectedReport.client_signer_name && <div style={{fontSize:12,fontWeight:500,marginBottom:6}}>{selectedReport.client_signer_name}</div>}
                    <img src={selectedReport.client_signature} style={{width:'100%',height:70,objectFit:'contain',border:'0.5px solid #eee',borderRadius:6}} />
                  </div>
                )}
              </div>
            )}

            {/* Azioni */}
            <div style={{display:'flex',gap:10,marginBottom:12}}>
              {!editMode
                ? <Btn variant="secondary" size="lg" icon={<I.pencil size={15} />} onClick={() => setEditMode(true)} style={{flex:1}}>Correggi</Btn>
                : <>
                  <Btn variant="primary" size="lg" icon={!saving && <I.save size={15} />} onClick={saveEdit} disabled={saving} style={{flex:1}}>{saving?'Salvataggio…':'Salva'}</Btn>
                  <Btn variant="secondary" size="lg" onClick={() => setEditMode(false)}>Annulla</Btn>
                </>
              }
              <Btn variant="secondary" size="lg" icon={<I.fileText size={15} />} onClick={() => previewPDF(selectedReport)} style={{flex:1}}>Anteprima PDF</Btn>
            </div>

            {!editMode && selectedReport.status!=='sent_to_client' && (
              <Btn variant="primary" size="lg" icon={!(sendingId===selectedReport.id) && <I.send size={16} />} onClick={() => sendToClient(selectedReport)} disabled={sendingId===selectedReport.id} style={{width:'100%',marginBottom:14}}>
                {sendingId===selectedReport.id?'Preparazione…':'Invia al cliente'}
              </Btn>
            )}
            {selectedReport.status==='sent_to_client' && (
              <div style={{padding:'12px 14px',background:T.c.greenLight,borderRadius:T.r.md,fontSize:T.f.md,color:'#1a5c1a',marginBottom:14,display:'flex',alignItems:'center',gap:8,border:'1px solid #cfe5b8'}}>
                <I.check size={16} /> Inviato al cliente il {fmtDT(selectedReport.sent_to_client_at)}
              </div>
            )}

            {!editMode && (
              <div style={{marginBottom:16}}>
                <Btn variant="danger" size="md" icon={<I.trash size={14} />} onClick={() => deleteReport(selectedReport)} style={{width:'100%'}}>
                  Sposta nel cestino
                </Btn>
              </div>
            )}

            {/* Cronologia */}
            {revisions.length>0 && (
              <div style={{background:'#fafafa',borderRadius:10,padding:'12px 16px',border:'1px solid #eee'}}>
                <div style={{fontSize:11,fontWeight:600,color:'#888',marginBottom:10}}>CRONOLOGIA MODIFICHE</div>
                {revisions.map((r,i) => (
                  <div key={i} style={{fontSize:12,color:'#555',marginBottom:6,paddingBottom:6,borderBottom:i<revisions.length-1?'0.5px solid #eee':'none'}}>
                    <span style={{color:'#999',fontSize:11}}>{fmtDT(r.changed_at)}</span> · <strong>{r.field_name}</strong>: <span style={{color:'#999',textDecoration:'line-through'}}>{r.old_value||'—'}</span> → <span style={{color:GREEN}}>{r.new_value||'—'}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        }
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// TAB: SPEDISCI
// ═══════════════════════════════════════════════════════════════════
function SpedisciTab({ currentAdmin }) {
  const confirmModal = useConfirm();
  const toast = useToast();
  const [view, setView] = useState('pending');
  const [reports, setReports] = useState([]);
  const [clients, setClients] = useState([]);
  const [selected, setSelected] = useState({});
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(null);
  const [archive, setArchive] = useState([]);
  const [archiveLoaded, setArchiveLoaded] = useState(false);
  const [archiveLoading, setArchiveLoading] = useState(false);
  const [archiveSearch, setArchiveSearch] = useState('');
  const [expandedMonths, setExpandedMonths] = useState({});
  const [expandedReport, setExpandedReport] = useState(null);
  const [resending, setResending] = useState(null);

  const load = useCallback(async () => {
    const c = await sb();
    const [rpt, cli] = await Promise.all([
      c.from('dr_reports').select('id,report_number,service_date,submitted_by_name,client_name,client_id,address,report_type,status,submitted_at').neq('status','sent_to_client').is('deleted_at', null).order('service_date',{ascending:false}),
      c.from('report_clients').select('*').order('name'),
    ]);
    if (rpt.data) setReports(rpt.data);
    if (cli.data) setClients(cli.data);
    setLoading(false);
  }, []);

  const loadArchive = useCallback(async () => {
    setArchiveLoading(true);
    const c = await sb();
    const oneYearAgo = new Date(); oneYearAgo.setFullYear(oneYearAgo.getFullYear()-1);
    const { data } = await c.from('dr_reports')
      .select('id,report_number,service_date,submitted_by_name,client_name,address,report_type,sent_to_client_at,status')
      .eq('status','sent_to_client')
      .is('deleted_at', null)
      .gte('service_date', oneYearAgo.toISOString().split('T')[0])
      .order('sent_to_client_at', { ascending: false });
    if (data) {
      setArchive(data);
      if (data.length > 0) {
        const d0 = new Date(data[0].sent_to_client_at || data[0].service_date);
        const firstKey = `${d0.getFullYear()}-${String(d0.getMonth()+1).padStart(2,'0')}`;
        setExpandedMonths({ [firstKey]: true });
      }
    }
    setArchiveLoaded(true);
    setArchiveLoading(false);
  }, []);

  useEffect(() => { load(); }, []);
  useEffect(() => { if (view === 'archive' && !archiveLoaded && !archiveLoading) loadArchive(); }, [view, archiveLoaded, archiveLoading, loadArchive]);

  const grouped = useMemo(() => {
    const g = {};
    reports.forEach(r => {
      if (!g[r.client_name]) g[r.client_name] = [];
      g[r.client_name].push(r);
    });
    return Object.entries(g).sort(([a],[b]) => a.localeCompare(b));
  }, [reports]);

  const isChecked = (id) => selected[id] !== false;
  const toggle = (id) => setSelected(s => ({...s,[id]:!isChecked(id)}));
  const toggleAll = (ids) => { const allOn = ids.every(id => isChecked(id)); const u={...selected}; ids.forEach(id=>{u[id]=!allOn;}); setSelected(u); };

  const sendGroup = async (clientName, rpts) => {
    const toSend = rpts.filter(r => isChecked(r.id));
    if (toSend.length===0) return;
    setSending(clientName);
    const clientObj = clients.find(cl => cl.name.toLowerCase()===clientName.toLowerCase());
    const email = clientObj?.email||'';
    try {
      const files = [];
      for (const r of toSend) {
        const doc = await generateReportPDF(r);
        const blob = doc.output('blob');
        files.push(new File([blob], `Rapporto_${r.report_number}.pdf`, {type:'application/pdf'}));
      }
      const subject = encodeURIComponent(`Rapporti di Servizio – ${clientName}`);
      const body = encodeURIComponent(`Spettabile Cliente,\n\nin allegato trasmettiamo i Rapporti di Servizio.\n\nCordiali saluti,\nDELTAgroup Security & Services AG`);
      let shareAborted = false;
      if (navigator.canShare && navigator.canShare({files})) {
        try {
          await navigator.share({files, title:`Rapporti ${clientName}`});
        } catch(err) {
          if (err && err.name === 'AbortError') shareAborted = true;
          else throw err;
        }
      } else {
        files.forEach(f => { const url=URL.createObjectURL(f); const a=document.createElement('a'); a.href=url; a.download=f.name; a.click(); });
        window.open(`mailto:${email}?subject=${subject}&body=${body}`);
      }
      if (shareAborted) { setSending(null); return; }
      const confirmed = await confirmModal({
        title: 'Conferma invio al cliente',
        message: `Hai effettivamente inviato i ${toSend.length} rapporto/i a ${clientName}?\n\nConferma SOLO se l'email è stata spedita al cliente.\nIn caso contrario i rapporti resteranno nella sezione Spedisci.`,
        confirmLabel: 'Sì, segna come inviati',
        cancelLabel: 'No, riprovo dopo',
        tone: 'info',
      });
      if (!confirmed) { setSending(null); return; }
      const c = await sb();
      const ids = toSend.map(r => r.id);
      await c.from('dr_reports').update({status:'sent_to_client',sent_to_client_at:new Date().toISOString()}).in('id',ids);
      for (const r of toSend) {
        await logAudit(currentAdmin, 'send', r, { recipient: email || null, bulk: true, group_size: toSend.length });
      }
      setReports(prev => prev.filter(r => !ids.includes(r.id)));
      setArchiveLoaded(false);
      toast.success(`${toSend.length} ${toSend.length===1?'rapporto inviato':'rapporti inviati'} a ${clientName}.`);
    } catch(e) { console.error(e); toast.error('Errore durante la preparazione dei PDF.'); }
    setSending(null);
  };

  const archiveGrouped = useMemo(() => {
    const q = archiveSearch.trim().toLowerCase();
    const filtered = q
      ? archive.filter(r => (r.client_name||'').toLowerCase().includes(q) || (r.report_number||'').toLowerCase().includes(q) || (r.submitted_by_name||'').toLowerCase().includes(q))
      : archive;
    const g = {};
    filtered.forEach(r => {
      const dStr = r.sent_to_client_at || r.service_date;
      const d = new Date(dStr);
      const key = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
      if (!g[key]) g[key] = { label: `${MONTHS_LONG[d.getMonth()]} ${d.getFullYear()}`, items: [] };
      g[key].items.push(r);
    });
    return Object.entries(g).sort((a,b) => b[0].localeCompare(a[0]));
  }, [archive, archiveSearch]);

  const previewArchive = async (id) => {
    try {
      const c = await sb();
      const { data } = await c.from('dr_reports').select('*').eq('id', id).single();
      if (!data) return;
      const doc = await generateReportPDF(data);
      window.open(URL.createObjectURL(doc.output('blob')), '_blank');
    } catch(e) { console.error(e); toast.error('Errore apertura PDF.'); }
  };

  const resendArchive = async (rep) => {
    setResending(rep.id);
    try {
      const c = await sb();
      const { data: full } = await c.from('dr_reports').select('*').eq('id', rep.id).single();
      if (!full) throw new Error('not found');
      const doc = await generateReportPDF(full);
      const blob = doc.output('blob');
      const file = new File([blob], `Rapporto_${full.report_number}.pdf`, {type:'application/pdf'});
      const clientObj = clients.find(cl => cl.name.toLowerCase() === (full.client_name||'').toLowerCase());
      const email = clientObj?.email || '';
      const subject = encodeURIComponent(`Rapporto di Servizio ${full.report_number} – ${full.client_name}`);
      const body = encodeURIComponent(`Spettabile Cliente,\n\nin allegato trasmettiamo nuovamente il Rapporto di Servizio N° ${full.report_number} del ${fromISO(full.service_date)}.\n\nCordiali saluti,\nDELTAgroup Security & Services AG`);
      let resendAborted = false;
      if (navigator.canShare && navigator.canShare({files:[file]})) {
        try { await navigator.share({files:[file], title:`Rapporto ${full.report_number}`}); }
        catch(err) {
          if (err && err.name === 'AbortError') resendAborted = true;
          else throw err;
        }
      } else {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href=url; a.download=file.name; a.click();
        window.open(`mailto:${email}?subject=${subject}&body=${body}`);
      }
      if (!resendAborted) {
        await logAudit(currentAdmin, 'resend', full, { recipient: email || null });
        toast.success(`Rapporto ${full.report_number} re-inviato.`);
      }
    } catch(e) { console.error(e); toast.error('Errore durante il re-invio.'); }
    setResending(null);
  };

  const Header = () => (
    <div style={{marginBottom:20}}>
      <div style={{fontWeight:600,fontSize:T.f.h,marginBottom:14,display:'flex',alignItems:'center',gap:9,color:T.c.text}}><I.send size={18} /> Spedisci</div>
      <div style={{display:'inline-flex',background:T.c.surfaceHover,borderRadius:T.r.md,padding:3,border:`1px solid ${T.c.border}`}}>
        <button onClick={() => setView('pending')} style={{padding:'7px 14px',border:'none',borderRadius:T.r.sm,background:view==='pending'?T.c.surface:'transparent',color:view==='pending'?T.c.text:T.c.textMuted,cursor:'pointer',fontSize:T.f.md,fontFamily:'inherit',fontWeight:view==='pending'?500:400,boxShadow:view==='pending'?T.sh.sm:'none',display:'inline-flex',alignItems:'center',gap:7}}><I.send size={13} /> Da inviare</button>
        <button onClick={() => setView('archive')} style={{padding:'7px 14px',border:'none',borderRadius:T.r.sm,background:view==='archive'?T.c.surface:'transparent',color:view==='archive'?T.c.text:T.c.textMuted,cursor:'pointer',fontSize:T.f.md,fontFamily:'inherit',fontWeight:view==='archive'?500:400,boxShadow:view==='archive'?T.sh.sm:'none',display:'inline-flex',alignItems:'center',gap:7}}><I.clock size={13} /> Archivio inviati</button>
      </div>
    </div>
  );

  if (loading && view==='pending') return <div style={{padding:28,maxWidth:820,boxSizing:'border-box'}}><Header /><div style={{padding:40,textAlign:'center',color:'#888'}}>Caricamento…</div></div>;

  if (view === 'archive') {
    return (
      <div style={{padding:28,maxWidth:820,overflowY:'auto',height:'100vh',boxSizing:'border-box'}}>
        <Header />
        <div style={{color:'#888',fontSize:13,marginBottom:14}}>Rapporti inviati negli ultimi 12 mesi · {archive.length} totali</div>
        <input value={archiveSearch} onChange={e=>setArchiveSearch(e.target.value)} placeholder="🔍 Cerca per cliente, N° rapporto o agente…" style={{width:'100%',padding:'10px 13px',border:'1px solid #ddd',borderRadius:9,fontSize:14,marginBottom:16,boxSizing:'border-box',fontFamily:'inherit'}} />
        {archiveLoading && <div style={{padding:40,textAlign:'center',color:'#888'}}>Caricamento…</div>}
        {!archiveLoading && archiveGrouped.length===0 && (
          <div style={{padding:40,textAlign:'center',color:'#888',background:'#fafafa',borderRadius:12,border:'1px solid #eee'}}>
            {archive.length===0 ? 'Nessun rapporto inviato negli ultimi 12 mesi.' : 'Nessun risultato per la ricerca.'}
          </div>
        )}
        {archiveGrouped.map(([key, group]) => {
          const isOpen = expandedMonths[key];
          return (
            <div key={key} style={{border:'1px solid #e0e0e0',borderRadius:12,marginBottom:12,overflow:'hidden'}}>
              <button onClick={() => setExpandedMonths(s => ({...s, [key]: !isOpen}))} style={{width:'100%',background:'#f5f5f5',padding:'12px 18px',border:'none',display:'flex',alignItems:'center',justifyContent:'space-between',cursor:'pointer',fontFamily:'inherit',textAlign:'left'}}>
                <div style={{display:'flex',alignItems:'center',gap:10}}>
                  <span style={{fontSize:11,color:'#666',transform:isOpen?'rotate(90deg)':'rotate(0deg)',transition:'transform 0.15s'}}>▶</span>
                  <div style={{fontWeight:500,fontSize:15}}>{group.label}</div>
                </div>
                <span style={{fontSize:12,background:GREEN_LIGHT,color:'#1a5c1a',padding:'3px 10px',borderRadius:6}}>{group.items.length} {group.items.length===1?'rapporto':'rapporti'}</span>
              </button>
              {isOpen && (
                <div>
                  {group.items.map((r,i) => {
                    const isExpanded = expandedReport === r.id;
                    return (
                      <div key={r.id} style={{borderTop:i>0?'0.5px solid #f0f0f0':'none'}}>
                        <div onClick={() => setExpandedReport(isExpanded?null:r.id)} style={{padding:'10px 18px',cursor:'pointer',display:'flex',alignItems:'center',gap:12,background:isExpanded?'#f8fbf8':'#fff'}}>
                          <div style={{flex:1,minWidth:0}}>
                            <div style={{fontSize:13,fontWeight:500}}>{r.client_name||'—'} <span style={{color:'#888',fontWeight:400}}>· {r.report_number}</span></div>
                            <div style={{fontSize:11,color:'#888',marginTop:2}}>Servizio {fromISO(r.service_date)} · da {r.submitted_by_name||'—'} · Inviato {r.sent_to_client_at?fmtDT(r.sent_to_client_at):'—'}</div>
                          </div>
                          <TypeBadge type={r.report_type} />
                          <span style={{fontSize:11,color:'#888',transform:isExpanded?'rotate(90deg)':'rotate(0deg)',transition:'transform 0.15s'}}>▶</span>
                        </div>
                        {isExpanded && (
                          <div style={{padding:'10px 18px 14px',background:'#f8fbf8',borderTop:'0.5px solid #e8e8e8',display:'flex',gap:8,flexWrap:'wrap'}}>
                            <button onClick={() => previewArchive(r.id)} style={{padding:'8px 14px',border:'1px solid #ddd',borderRadius:8,background:'#fff',cursor:'pointer',fontSize:13,fontFamily:'inherit'}}>📄 Anteprima PDF</button>
                            <button onClick={() => resendArchive(r)} disabled={resending===r.id} style={{padding:'8px 14px',border:'none',borderRadius:8,background:GREEN,color:'#fff',cursor:'pointer',fontSize:13,fontFamily:'inherit',fontWeight:500,opacity:resending===r.id?0.6:1}}>
                              {resending===r.id?'Preparazione…':'📤 Re-invia al cliente'}
                            </button>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    );
  }

  return (
    <div style={{padding:28,maxWidth:820,overflowY:'auto',height:'100vh',boxSizing:'border-box'}}>
      <Header />
      <div style={{color:'#888',fontSize:13,marginBottom:24}}>Rapporti da inviare, raggruppati per cliente.</div>
      {grouped.length===0 && <div style={{padding:40,textAlign:'center',color:'#888',background:'#fafafa',borderRadius:12,border:'1px solid #eee'}}>Nessun rapporto da inviare 🎉</div>}
      {grouped.map(([clientName, rpts]) => {
        const clientObj = clients.find(cl => cl.name.toLowerCase()===clientName.toLowerCase());
        const ids = rpts.map(r=>r.id);
        const nSelected = rpts.filter(r=>isChecked(r.id)).length;
        return (
          <div key={clientName} style={{border:'1px solid #e0e0e0',borderRadius:12,marginBottom:16,overflow:'hidden'}}>
            <div style={{background:'#f5f5f5',padding:'12px 18px',display:'flex',alignItems:'center',justifyContent:'space-between',borderBottom:'1px solid #e0e0e0'}}>
              <div>
                <div style={{fontWeight:500,fontSize:15}}>{clientName}</div>
                <div style={{fontSize:12,color:clientObj?.email?'#777':'#e24b4a'}}>{clientObj?.email||'Email non registrata — vai su Clienti per aggiungerla'}</div>
              </div>
              <span style={{fontSize:12,background:'#fcebeb',color:'#a32d2d',padding:'3px 10px',borderRadius:6}}>{rpts.length} da inviare</span>
            </div>
            <div style={{padding:'0 18px'}}>
              <div style={{display:'flex',alignItems:'center',gap:8,padding:'8px 0',borderBottom:'0.5px solid #f0f0f0'}}>
                <input type="checkbox" checked={ids.every(id=>isChecked(id))} onChange={() => toggleAll(ids)} style={{accentColor:GREEN}} />
                <span style={{fontSize:12,color:'#888'}}>Seleziona tutti</span>
              </div>
              {rpts.map(r => (
                <label key={r.id} style={{display:'flex',alignItems:'center',gap:12,padding:'10px 0',borderBottom:'0.5px solid #f5f5f5',cursor:'pointer'}}>
                  <input type="checkbox" checked={isChecked(r.id)} onChange={() => toggle(r.id)} style={{accentColor:GREEN,flexShrink:0}} />
                  <div style={{flex:1}}>
                    <div style={{fontSize:13}}>{r.report_number} · {r.submitted_by_name} · {fromISO(r.service_date)}</div>
                    <div style={{fontSize:11,color:'#888'}}>{r.address}</div>
                  </div>
                  <TypeBadge type={r.report_type} />
                </label>
              ))}
            </div>
            <div style={{padding:'12px 18px',background:'#fafafa',borderTop:'1px solid #e0e0e0',display:'flex',alignItems:'center',gap:10}}>
              {clientObj?.email && (
                <div style={{display:'flex',alignItems:'center',gap:6,flex:1,background:'#fff',padding:'7px 11px',borderRadius:7,border:'1px solid #e8e8e8'}}>
                  <span style={{fontSize:13,color:'#555',flex:1}}>📧 {clientObj.email}</span>
                  <button onClick={() => navigator.clipboard?.writeText(clientObj.email)} style={{background:GREEN,color:'#fff',border:'none',borderRadius:6,padding:'3px 10px',cursor:'pointer',fontSize:11,fontFamily:'inherit'}}>Copia</button>
                </div>
              )}
              <button onClick={() => sendGroup(clientName, rpts)} disabled={sending===clientName||nSelected===0} style={{padding:'10px 20px',background:GREEN,color:'#fff',border:'none',borderRadius:9,cursor:'pointer',fontSize:13,fontWeight:500,fontFamily:'inherit',whiteSpace:'nowrap',opacity:sending===clientName||nSelected===0?0.5:1}}>
                {sending===clientName?'Preparazione…':`📤 Invia ${nSelected} PDF`}
              </button>
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// TAB: CLIENTI
// ═══════════════════════════════════════════════════════════════════
function ClientiTab() {
  const confirmModal = useConfirm();
  const toast = useToast();
  const [clients, setClients] = useState([]);
  const [search, setSearch] = useState('');
  const [form, setForm] = useState({name:'',email:'',notes:''});
  const [editing, setEditing] = useState(null);
  const [showForm, setShowForm] = useState(false);

  useEffect(() => {
    sb().then(c => c.from('report_clients').select('*').order('name')).then(({data}) => { if(data) setClients(data); });
  }, []);

  const save = async () => {
    const c = await sb();
    if (editing) {
      const {data} = await c.from('report_clients').update({name:form.name,email:form.email,notes:form.notes,updated_at:new Date().toISOString()}).eq('id',editing).select().single();
      if (data) setClients(prev => prev.map(cl => cl.id===editing?data:cl));
    } else {
      const {data} = await c.from('report_clients').insert({name:form.name,email:form.email,notes:form.notes}).select().single();
      if (data) setClients(prev => [...prev,data].sort((a,b)=>a.name.localeCompare(b.name)));
    }
    setForm({name:'',email:'',notes:''}); setEditing(null); setShowForm(false);
  };

  const del = async (id) => {
    const cl = clients.find(c => c.id === id);
    const ok = await confirmModal({
      title: 'Eliminare questo cliente?',
      message: `${cl?.name || ''}\n${cl?.email || ''}`,
      confirmLabel: 'Elimina',
      danger: true,
    });
    if (!ok) return;
    const c = await sb();
    await c.from('report_clients').delete().eq('id',id);
    setClients(prev => prev.filter(cl => cl.id!==id));
    toast.success('Cliente eliminato.');
  };

  const startEdit = (cl) => { setForm({name:cl.name,email:cl.email,notes:cl.notes||''}); setEditing(cl.id); setShowForm(true); };
  const filtered = clients.filter(cl => cl.name.toLowerCase().includes(search.toLowerCase()) || cl.email.toLowerCase().includes(search.toLowerCase()));

  return (
    <div style={{padding:28,maxWidth:700,overflowY:'auto',height:'100vh',boxSizing:'border-box'}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:20}}>
        <div><div style={{fontWeight:600,fontSize:T.f.h,display:'flex',alignItems:'center',gap:9,color:T.c.text}}><I.building size={18} /> Anagrafica Clienti</div><div style={{fontSize:T.f.md,color:T.c.textMuted,marginTop:4}}>Email per l'invio dei rapporti</div></div>
        <button onClick={() => {setForm({name:'',email:'',notes:''});setEditing(null);setShowForm(true);}} style={{padding:'9px 16px',background:GREEN,color:'#fff',border:'none',borderRadius:9,cursor:'pointer',fontSize:13,fontWeight:500,fontFamily:'inherit'}}>+ Aggiungi cliente</button>
      </div>
      {showForm && (
        <div style={{background:'#fafafa',borderRadius:12,padding:20,marginBottom:20,border:'1px solid #e0e0e0'}}>
          <div style={{fontWeight:500,fontSize:14,marginBottom:14}}>{editing?'Modifica cliente':'Nuovo cliente'}</div>
          <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12}}>
            <div><div style={{fontSize:11,color:'#888',marginBottom:4}}>Nome cliente *</div><input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} style={{width:'100%',padding:'9px 11px',border:'1px solid #ddd',borderRadius:8,fontSize:13,boxSizing:'border-box',fontFamily:'inherit'}} placeholder="Es. SPALU – DSU" /></div>
            <div><div style={{fontSize:11,color:'#888',marginBottom:4}}>Email *</div><input value={form.email} onChange={e=>setForm(f=>({...f,email:e.target.value}))} type="email" style={{width:'100%',padding:'9px 11px',border:'1px solid #ddd',borderRadius:8,fontSize:13,boxSizing:'border-box',fontFamily:'inherit'}} placeholder="rapporti@cliente.ch" /></div>
            <div style={{gridColumn:'1/-1'}}><div style={{fontSize:11,color:'#888',marginBottom:4}}>Note</div><input value={form.notes} onChange={e=>setForm(f=>({...f,notes:e.target.value}))} style={{width:'100%',padding:'9px 11px',border:'1px solid #ddd',borderRadius:8,fontSize:13,boxSizing:'border-box',fontFamily:'inherit'}} placeholder="Note opzionali" /></div>
          </div>
          <div style={{display:'flex',gap:10,marginTop:14}}>
            <button onClick={save} disabled={!form.name||!form.email} style={{padding:'9px 20px',background:GREEN,color:'#fff',border:'none',borderRadius:8,cursor:'pointer',fontSize:13,fontWeight:500,fontFamily:'inherit',opacity:!form.name||!form.email?0.5:1}}>Salva</button>
            <button onClick={() => {setShowForm(false);setEditing(null);}} style={{padding:'9px 16px',border:'1px solid #ddd',borderRadius:8,background:'#fff',cursor:'pointer',fontSize:13,fontFamily:'inherit'}}>Annulla</button>
          </div>
        </div>
      )}
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Cerca cliente o email…" style={{width:'100%',padding:'10px 13px',border:'1px solid #ddd',borderRadius:9,fontSize:14,marginBottom:14,boxSizing:'border-box',fontFamily:'inherit'}} />
      {filtered.map(cl => (
        <div key={cl.id} style={{display:'flex',alignItems:'center',justifyContent:'space-between',padding:'13px 16px',background:'#fff',borderRadius:10,marginBottom:8,border:'0.5px solid #e8e8e8'}}>
          <div>
            <div style={{fontWeight:500,fontSize:14}}>{cl.name}</div>
            <div style={{fontSize:12,color:'#777',marginTop:2}}>📧 {cl.email}</div>
            {cl.notes && <div style={{fontSize:11,color:'#aaa',marginTop:2}}>{cl.notes}</div>}
          </div>
          <div style={{display:'flex',gap:8}}>
            <button onClick={() => startEdit(cl)} style={{padding:'6px 12px',border:'1px solid #ddd',borderRadius:7,background:'#fff',cursor:'pointer',fontSize:12,fontFamily:'inherit'}}>✏️ Modifica</button>
            <button onClick={() => del(cl.id)} style={{padding:'6px 12px',border:'1px solid #ffcccc',borderRadius:7,background:'#fff',cursor:'pointer',fontSize:12,color:'#cc0000',fontFamily:'inherit'}}>🗑</button>
          </div>
        </div>
      ))}
      {filtered.length===0 && <div style={{textAlign:'center',color:'#aaa',padding:30}}>Nessun cliente trovato.</div>}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// TAB: COLLABORATORI
// ═══════════════════════════════════════════════════════════════════
function CollaboratoriTab({ currentAdmin }) {
  const isSuper = !!currentAdmin?.is_super;
  const confirmModal = useConfirm();
  const alertModal = useAlertModal();
  const toast = useToast();
  const [collabs, setCollabs] = useState([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [importing, setImporting] = useState(false);

  const load = async () => {
    setLoading(true);
    const c = await sb();
    const {data} = await c.from('report_collaborators').select('*').order('agent_name');
    if (data) setCollabs(data);
    setLoading(false);
  };
  useEffect(() => { load(); }, []);

  const toggleActive = async (id, current) => {
    const c = await sb();
    await c.from('report_collaborators').update({is_active:!current,updated_at:new Date().toISOString()}).eq('id',id);
    setCollabs(prev => prev.map(cl => cl.id===id ? {...cl,is_active:!current} : cl));
  };

  const resetPin = async (id, name) => {
    const ok = await confirmModal({
      title: `Resettare il PIN di ${name}?`,
      message: 'Verrà generato un nuovo PIN e il collaboratore dovrà rifare il primo accesso.',
      confirmLabel: 'Genera nuovo PIN',
    });
    if (!ok) return;
    const c = await sb();
    const {data:pin} = await c.rpc('generate_random_pin');
    await c.from('report_collaborators').update({pin,pin_revealed:false,pin_revealed_at:null,regulation_accepted:false,regulation_accepted_at:null,regulation_version:0,updated_at:new Date().toISOString()}).eq('id',id);
    setCollabs(prev => prev.map(cl => cl.id===id ? {...cl,pin,pin_revealed:false,regulation_accepted:false} : cl));
    await alertModal({ title: `Nuovo PIN per ${name}`, message: `PIN: ${pin}\n\nComunicalo al collaboratore: lo userà al primo accesso.`, tone: 'success' });
  };

  const importFromPlan = async () => {
    const ok = await confirmModal({
      title: 'Importare collaboratori da PLAN?',
      message: 'Vengono importati i collaboratori attivi presenti su PLAN che non sono ancora qui.',
      confirmLabel: 'Importa',
    });
    if (!ok) return;
    setImporting(true);
    const c = await sb();
    const {data} = await c.rpc('import_agents_to_report');
    toast.success(`${data} ${data===1?'collaboratore importato':'collaboratori importati'}.`);
    load();
    setImporting(false);
  };

  const filtered = collabs.filter(cl => cl.agent_name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div style={{padding:28,overflowY:'auto',height:'100vh',boxSizing:'border-box'}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:20}}>
        <div><div style={{fontWeight:600,fontSize:T.f.h,display:'flex',alignItems:'center',gap:9,color:T.c.text}}><I.users size={18} /> Collaboratori</div><div style={{fontSize:T.f.md,color:T.c.textMuted,marginTop:4}}>Gestione accessi e PIN · {collabs.length} totali</div></div>
        <button onClick={importFromPlan} disabled={importing} style={{padding:'9px 16px',background:'#1d4ed8',color:'#fff',border:'none',borderRadius:9,cursor:'pointer',fontSize:13,fontWeight:500,fontFamily:'inherit'}}>
          {importing?'Import in corso…':'⬇ Importa da PLAN'}
        </button>
      </div>
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Cerca collaboratore…" style={{width:'100%',padding:'10px 13px',border:'1px solid #ddd',borderRadius:9,fontSize:14,marginBottom:14,boxSizing:'border-box',fontFamily:'inherit'}} />
      {loading && <div style={{textAlign:'center',color:'#888',padding:30}}>Caricamento…</div>}
      <div style={{background:'#fff',borderRadius:12,border:'0.5px solid #e0e0e0',overflow:'hidden'}}>
        <table style={{width:'100%',borderCollapse:'collapse',fontSize:13}}>
          <thead>
            <tr style={{background:'#f5f5f5'}}>
              {['Collaboratore','PIN','Primo accesso','Regolamento','Stato','Azioni'].map(h => (
                <th key={h} style={{padding:'10px 14px',textAlign:'left',fontSize:11,fontWeight:600,color:'#666',textTransform:'uppercase',letterSpacing:0.5}}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map((cl,i) => (
              <tr key={cl.id} style={{borderTop:i>0?'0.5px solid #f0f0f0':'none'}}>
                <td style={{padding:'11px 14px',fontWeight:500}}>{cl.agent_name}</td>
                <td style={{padding:'11px 14px',fontFamily:'monospace',fontSize:14,color:cl.pin_revealed?'#aaa':GREEN,fontWeight:600}}>{isSuper?(cl.pin_revealed?'••••••':cl.pin):'••••••'}</td>
                <td style={{padding:'11px 14px',fontSize:12,color:'#888'}}>{cl.pin_revealed?fmtDT(cl.pin_revealed_at):'— Non ancora'}</td>
                <td style={{padding:'11px 14px'}}>{cl.regulation_accepted?<span style={{color:GREEN}}>✓ Accettato</span>:<span style={{color:'#ccc'}}>— Non ancora</span>}</td>
                <td style={{padding:'11px 14px'}}>{cl.is_active?<span style={{color:GREEN,fontWeight:500}}>● Attivo</span>:<span style={{color:'#999'}}>○ Disabilitato</span>}</td>
                <td style={{padding:'11px 14px'}}>
                  <div style={{display:'flex',gap:6}}>
                    <button onClick={() => toggleActive(cl.id,cl.is_active)} style={{padding:'4px 10px',border:`1px solid ${cl.is_active?'#ffcccc':'#ccffcc'}`,borderRadius:6,background:'#fff',cursor:'pointer',fontSize:11,color:cl.is_active?'#cc0000':GREEN,fontFamily:'inherit'}}>
                      {cl.is_active?'Disabilita':'Abilita'}
                    </button>
                    <button onClick={() => resetPin(cl.id,cl.agent_name)} style={{padding:'4px 10px',border:'1px solid #ddd',borderRadius:6,background:'#fff',cursor:'pointer',fontSize:11,fontFamily:'inherit'}}>Reset PIN</button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {filtered.length===0 && !loading && <div style={{textAlign:'center',color:'#aaa',padding:30}}>Nessun collaboratore trovato.</div>}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// TAB: AMMINISTRATORI
// ═══════════════════════════════════════════════════════════════════
function AmministratoriTab({ currentAdmin, onlineAdmins }) {
  const online = onlineAdmins || {};
  const confirmModal = useConfirm();
  const alertModal = useAlertModal();
  const promptModal = usePromptModal();
  const toast = useToast();
  const [admins, setAdmins] = useState([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [adding, setAdding] = useState(false);

  const load = async () => {
    setLoading(true);
    const c = await sb();
    const { data } = await c.from('report_admins_safe').select('*').order('admin_name');
    if (data) setAdmins(data);
    setLoading(false);
  };
  useEffect(() => { load(); }, []);

  const genPin = () => String(Math.floor(100000 + Math.random()*900000));

  const addAdmin = async () => {
    const name = await promptModal({
      title: 'Nuovo amministratore',
      message: 'Inserisci il nome completo (es. POLETTI MARCO). Verrà creato come admin standard; potrai promuoverlo a super dopo.',
      placeholder: 'NOME COGNOME',
    });
    if (!name) return;
    const cleanName = name.trim().toUpperCase();
    if (!cleanName) return;
    if (admins.some(a => a.admin_name === cleanName)) { await alertModal({ title: 'Nome già usato', message: 'Esiste già un amministratore con questo nome.', tone: 'warning' }); return; }
    setAdding(true);
    try {
      const c = await sb();
      const pin = genPin();
      const { data, error } = await c.rpc('create_admin', { p_token: currentAdmin.token, p_admin_name: cleanName, p_pin: pin });
      if (error) throw error;
      const created = Array.isArray(data) ? data[0] : data;
      if (created) setAdmins(prev => [...prev, created].sort((a,b) => a.admin_name.localeCompare(b.admin_name)));
      await alertModal({
        title: `${cleanName} aggiunto`,
        message: `PIN: ${pin}\n\nComunica il PIN all'utente: lo userà al primo accesso.\nQuesto è l'unico momento in cui il PIN è visibile.`,
        tone: 'success',
      });
    } catch(e) { console.error(e); toast.error('Errore durante la creazione.'); }
    setAdding(false);
  };

  const resetPin = async (id, name) => {
    const ok = await confirmModal({
      title: `Resettare il PIN di ${name}?`,
      message: 'Verrà generato un nuovo PIN che dovrai comunicargli. Il vecchio non funzionerà più.',
      confirmLabel: 'Genera nuovo PIN',
    });
    if (!ok) return;
    try {
      const c = await sb();
      const pin = genPin();
      const { error } = await c.rpc('reset_admin_pin', { p_token: currentAdmin.token, p_admin_id: id, p_new_pin: pin });
      if (error) throw error;
      await alertModal({
        title: `Nuovo PIN per ${name}`,
        message: `PIN: ${pin}\n\nComunicalo all'utente. Questo è l'unico momento in cui è visibile.`,
        tone: 'success',
      });
    } catch(e) { console.error(e); toast.error('Errore durante il reset del PIN.'); }
  };

  const toggleActive = async (a) => {
    if (a.id === currentAdmin?.id && a.is_active) { toast.warning('Non puoi disabilitare te stesso.'); return; }
    try {
      const c = await sb();
      const { error } = await c.rpc('set_admin_active', { p_token: currentAdmin.token, p_admin_id: a.id, p_is_active: !a.is_active });
      if (error) throw error;
      setAdmins(prev => prev.map(x => x.id===a.id ? {...x, is_active: !a.is_active} : x));
      toast.success(`${a.admin_name} ${!a.is_active ? 'abilitato' : 'disabilitato'}.`);
    } catch(e) { console.error(e); toast.error('Errore.'); }
  };

  const forceLogout = async (a) => {
    if (a.id === currentAdmin?.id) { toast.warning('Per disconnettere te stesso usa "Esci" in basso a sinistra.'); return; }
    const ok = await confirmModal({
      title: `Forzare la disconnessione di ${a.admin_name}?`,
      message: 'Tutte le sue sessioni attive verranno invalidate. Dovrà rifare il login.',
      confirmLabel: 'Disconnetti',
      tone: 'warning',
    });
    if (!ok) return;
    try {
      const c = await sb();
      const { error } = await c.rpc('force_logout_admin', { p_token: currentAdmin.token, p_target_admin_id: a.id });
      if (error) throw error;
      toast.success(`${a.admin_name} è stato disconnesso. Sarà sloggato entro 1 minuto.`);
    } catch(e) { console.error(e); toast.error('Errore durante la disconnessione.'); }
  };

  const toggleSuper = async (a) => {
    if (a.id === currentAdmin?.id) { toast.warning('Non puoi cambiare il tuo livello.'); return; }
    const next = !a.is_super;
    const ok = await confirmModal({
      title: next ? `Rendere ${a.admin_name} super-admin?` : `Togliere super-admin a ${a.admin_name}?`,
      message: next ? 'Avrà pieno accesso al pannello (gestione admin, cestino, cronologia, regolamento).' : 'Avrà accesso solo a Inbox, Spedisci e Clienti.',
      confirmLabel: next ? 'Rendi super' : 'Togli super',
      tone: 'warning',
    });
    if (!ok) return;
    try {
      const c = await sb();
      const { error } = await c.rpc('set_admin_super', { p_token: currentAdmin.token, p_admin_id: a.id, p_is_super: next });
      if (error) throw error;
      setAdmins(prev => prev.map(x => x.id===a.id ? {...x, is_super: next} : x));
      toast.success(`${a.admin_name} ${next ? 'promosso a super-admin' : 'declassato ad admin standard'}.`);
    } catch(e) { console.error(e); toast.error('Errore.'); }
  };

  const removeAdmin = async (a) => {
    if (a.id === currentAdmin?.id) { toast.warning('Non puoi eliminare te stesso.'); return; }
    const ok = await confirmModal({
      title: `Eliminare ${a.admin_name}?`,
      message: 'L\'utente non potrà più accedere al pannello. Tutte le sue sessioni attive verranno invalidate.\n\nDigita ELIMINA per confermare:',
      confirmLabel: 'Elimina definitivamente',
      danger: true,
      requireText: 'ELIMINA',
    });
    if (!ok) return;
    try {
      const c = await sb();
      const { error } = await c.rpc('delete_admin', { p_token: currentAdmin.token, p_admin_id: a.id });
      if (error) throw error;
      setAdmins(prev => prev.filter(x => x.id !== a.id));
      toast.success(`${a.admin_name} eliminato.`);
    } catch(e) { console.error(e); toast.error('Errore.'); }
  };

  const filtered = admins.filter(a => a.admin_name.toLowerCase().includes(search.toLowerCase()));

  return (
    <div style={{padding:28,overflowY:'auto',height:'100vh',boxSizing:'border-box'}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:20}}>
        <div><div style={{fontWeight:600,fontSize:T.f.h,display:'flex',alignItems:'center',gap:9,color:T.c.text}}><I.key size={18} /> Amministratori</div><div style={{fontSize:T.f.md,color:T.c.textMuted,marginTop:4}}>Gestione accessi al pannello · {admins.length} totali · <span style={{color:T.c.online,fontWeight:500}}>{Object.keys(online).length} online ora</span></div></div>
        <button onClick={addAdmin} disabled={adding} style={{padding:'9px 16px',background:GREEN,color:'#fff',border:'none',borderRadius:9,cursor:'pointer',fontSize:13,fontWeight:500,fontFamily:'inherit'}}>
          {adding?'Creazione…':'+ Aggiungi amministratore'}
        </button>
      </div>
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Cerca amministratore…" style={{width:'100%',padding:'10px 13px',border:'1px solid #ddd',borderRadius:9,fontSize:14,marginBottom:14,boxSizing:'border-box',fontFamily:'inherit'}} />
      {loading && <div style={{textAlign:'center',color:'#888',padding:30}}>Caricamento…</div>}
      <div style={{background:'#fff',borderRadius:12,border:'0.5px solid #e0e0e0',overflow:'hidden'}}>
        <table style={{width:'100%',borderCollapse:'collapse',fontSize:13}}>
          <thead>
            <tr style={{background:'#f5f5f5'}}>
              {['Amministratore','PIN','Ultimo accesso','Stato','Azioni'].map(h => (
                <th key={h} style={{padding:'10px 14px',textAlign:'left',fontSize:11,fontWeight:600,color:'#666',textTransform:'uppercase',letterSpacing:0.5}}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map((a,i) => (
              <tr key={a.id} style={{borderTop:i>0?'0.5px solid #f0f0f0':'none'}}>
                <td style={{padding:'11px 14px',fontWeight:500}}>
                  <span title={online[a.id]?'Online ora':'Non in linea'} style={{display:'inline-block',width:8,height:8,borderRadius:'50%',marginRight:8,background:online[a.id]?'#22c55e':'#d4d4d4',verticalAlign:'middle'}} />
                  {a.admin_name}
                  {a.id===currentAdmin?.id && <span style={{marginLeft:8,fontSize:10,padding:'2px 6px',background:GREEN_LIGHT,color:'#1a5c1a',borderRadius:4}}>tu</span>}
                  {a.is_super && <span style={{marginLeft:6,fontSize:9,padding:'1px 5px',background:'#b87333',color:'#fff',borderRadius:3,letterSpacing:0.5}}>SUPER</span>}
                </td>
                <td style={{padding:'11px 14px',fontSize:11,color:'#888',fontStyle:'italic'}}>•••••• <span style={{fontSize:10}}>(non visualizzabile)</span></td>
                <td style={{padding:'11px 14px',fontSize:12,color:'#888'}}>{a.last_login_at?fmtDT(a.last_login_at):'— Mai'}</td>
                <td style={{padding:'11px 14px'}}>{a.is_active?<span style={{color:GREEN,fontWeight:500}}>● Attivo</span>:<span style={{color:'#999'}}>○ Disabilitato</span>}</td>
                <td style={{padding:'11px 14px'}}>
                  <div style={{display:'flex',gap:6,flexWrap:'wrap'}}>
                    <button onClick={() => toggleActive(a)} disabled={a.id===currentAdmin?.id} style={{padding:'4px 10px',border:`1px solid ${a.is_active?'#ffcccc':'#ccffcc'}`,borderRadius:6,background:'#fff',cursor:a.id===currentAdmin?.id?'not-allowed':'pointer',fontSize:11,color:a.is_active?'#cc0000':GREEN,fontFamily:'inherit',opacity:a.id===currentAdmin?.id?0.4:1}}>
                      {a.is_active?'Disabilita':'Abilita'}
                    </button>
                    <button onClick={() => resetPin(a.id,a.admin_name)} style={{padding:'4px 10px',border:'1px solid #ddd',borderRadius:6,background:'#fff',cursor:'pointer',fontSize:11,fontFamily:'inherit'}}>Reset PIN</button>
                    <button onClick={() => toggleSuper(a)} disabled={a.id===currentAdmin?.id} style={{padding:'4px 10px',border:'1px solid #d8b78a',borderRadius:6,background:'#fff',color:'#9a5a14',cursor:a.id===currentAdmin?.id?'not-allowed':'pointer',fontSize:11,fontFamily:'inherit',opacity:a.id===currentAdmin?.id?0.4:1}}>
                      {a.is_super?'Togli super':'Rendi super'}
                    </button>
                    <button onClick={() => forceLogout(a)} disabled={a.id===currentAdmin?.id} style={{padding:'4px 10px',border:'1px solid #c8d8f0',borderRadius:6,background:'#fff',color:'#0b5e8a',cursor:a.id===currentAdmin?.id?'not-allowed':'pointer',fontSize:11,fontFamily:'inherit',opacity:a.id===currentAdmin?.id?0.4:1}} title={online[a.id]?'Disconnetti tutte le sessioni (utente online)':'Invalida tutte le sessioni salvate'}>Disconnetti</button>
                    <button onClick={() => removeAdmin(a)} disabled={a.id===currentAdmin?.id} style={{padding:'4px 10px',border:'1px solid #f0c8c8',borderRadius:6,background:'#fff',color:'#a32d2d',cursor:a.id===currentAdmin?.id?'not-allowed':'pointer',fontSize:11,fontFamily:'inherit',opacity:a.id===currentAdmin?.id?0.4:1}}>Elimina</button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {filtered.length===0 && !loading && <div style={{textAlign:'center',color:'#aaa',padding:30}}>Nessun amministratore trovato.</div>}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// TAB: CRONOLOGIA (audit log)
// ═══════════════════════════════════════════════════════════════════
const ACTION_LABEL = { edit:'Modifica', delete:'Eliminazione', send:'Invio', resend:'Re-invio' };
const ACTION_COLOR = { edit:'#0b5e8a', delete:'#a32d2d', send:'#1a5c1a', resend:'#854f0b' };
const ACTION_ICON  = { edit:'✏️', delete:'🗑', send:'📤', resend:'🔁' };

function CronologiaTab() {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filterAdmin, setFilterAdmin] = useState('');
  const [filterAction, setFilterAction] = useState('');
  const [search, setSearch] = useState('');
  const [expandedId, setExpandedId] = useState(null);

  const load = async () => {
    setLoading(true);
    const c = await sb();
    const { data } = await c.from('report_audit_log').select('*').order('created_at', { ascending: false }).limit(1000);
    if (data) setRows(data);
    setLoading(false);
  };
  useEffect(() => { load(); }, []);

  const admins = useMemo(() => Array.from(new Set(rows.map(r => r.admin_name))).sort(), [rows]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return rows.filter(r => {
      if (filterAdmin && r.admin_name !== filterAdmin) return false;
      if (filterAction && r.action !== filterAction) return false;
      if (q) {
        const hay = `${r.report_number||''} ${r.report_client_name||''} ${r.admin_name||''}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
  }, [rows, filterAdmin, filterAction, search]);

  return (
    <div style={{padding:28,overflowY:'auto',height:'100vh',boxSizing:'border-box'}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:14}}>
        <div><div style={{fontWeight:600,fontSize:T.f.h,display:'flex',alignItems:'center',gap:9,color:T.c.text}}><I.clock size={18} /> Cronologia azioni</div><div style={{fontSize:T.f.md,color:T.c.textMuted,marginTop:4}}>Ultime {rows.length} azioni · {filtered.length} visibili</div></div>
        <button onClick={load} style={{padding:'7px 12px',border:'1px solid #ddd',borderRadius:7,background:'#fff',cursor:'pointer',fontSize:12,fontFamily:'inherit'}}>⟳ Aggiorna</button>
      </div>
      <div style={{display:'grid',gridTemplateColumns:'1fr 180px 180px',gap:10,marginBottom:14}}>
        <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Cerca N°, cliente o admin…" style={{padding:'9px 12px',border:'1px solid #ddd',borderRadius:8,fontSize:13,boxSizing:'border-box',fontFamily:'inherit'}} />
        <select value={filterAdmin} onChange={e=>setFilterAdmin(e.target.value)} style={{padding:'9px 12px',border:'1px solid #ddd',borderRadius:8,fontSize:13,boxSizing:'border-box',fontFamily:'inherit',background:'#fff'}}>
          <option value="">Tutti gli admin</option>
          {admins.map(a => <option key={a} value={a}>{a}</option>)}
        </select>
        <select value={filterAction} onChange={e=>setFilterAction(e.target.value)} style={{padding:'9px 12px',border:'1px solid #ddd',borderRadius:8,fontSize:13,boxSizing:'border-box',fontFamily:'inherit',background:'#fff'}}>
          <option value="">Tutte le azioni</option>
          {Object.entries(ACTION_LABEL).map(([k,v]) => <option key={k} value={k}>{v}</option>)}
        </select>
      </div>
      {loading && <div style={{textAlign:'center',color:'#888',padding:30}}>Caricamento…</div>}
      {!loading && filtered.length===0 && <div style={{textAlign:'center',color:'#aaa',padding:30,background:'#fafafa',borderRadius:10,border:'1px solid #eee'}}>Nessuna azione corrispondente.</div>}
      <div style={{background:'#fff',borderRadius:12,border:'0.5px solid #e0e0e0',overflow:'hidden'}}>
        {filtered.map((r,i) => {
          const isOpen = expandedId === r.id;
          return (
            <div key={r.id} style={{borderTop:i>0?'0.5px solid #f0f0f0':'none'}}>
              <div onClick={() => setExpandedId(isOpen?null:r.id)} style={{padding:'11px 16px',cursor:'pointer',display:'flex',alignItems:'center',gap:14,background:isOpen?'#fafafa':'#fff'}}>
                <span style={{fontSize:18}}>{ACTION_ICON[r.action]||'•'}</span>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontSize:13}}>
                    <span style={{fontWeight:500,color:ACTION_COLOR[r.action]||'#333'}}>{ACTION_LABEL[r.action]||r.action}</span>
                    <span style={{color:'#888'}}> · rapporto {r.report_number||'—'} {r.report_client_name?`(${r.report_client_name})`:''}</span>
                  </div>
                  <div style={{fontSize:11,color:'#888',marginTop:2}}>{r.admin_name} · {fmtDT(r.created_at)}</div>
                </div>
                <span style={{fontSize:11,color:'#888',transform:isOpen?'rotate(90deg)':'rotate(0deg)',transition:'transform 0.15s'}}>▶</span>
              </div>
              {isOpen && r.details && (
                <div style={{padding:'10px 16px 14px 48px',background:'#fafafa',borderTop:'0.5px solid #f0f0f0',fontSize:12,color:'#555'}}>
                  {r.action==='edit' && Array.isArray(r.details.fields) ? (
                    <div>
                      {r.details.fields.map((f,j) => (
                        <div key={j} style={{marginBottom:4}}>
                          <strong>{f.field}:</strong> <span style={{color:'#999',textDecoration:'line-through'}}>{f.old||'—'}</span> → <span style={{color:GREEN}}>{f.new||'—'}</span>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <pre style={{margin:0,fontFamily:'inherit',whiteSpace:'pre-wrap',fontSize:12}}>{JSON.stringify(r.details, null, 2)}</pre>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// TAB: CESTINO (soft-deleted reports, super-only)
// ═══════════════════════════════════════════════════════════════════
function CestinoTab({ currentAdmin }) {
  const confirmModal = useConfirm();
  const toast = useToast();
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [busyId, setBusyId] = useState(null);

  const load = async () => {
    setLoading(true);
    const c = await sb();
    const { data } = await c.from('dr_reports').select('id,report_number,service_date,submitted_by_name,client_name,address,report_type,deleted_at,deleted_by_admin_name').not('deleted_at', 'is', null).order('deleted_at', { ascending: false });
    if (data) setRows(data);
    setLoading(false);
  };
  useEffect(() => { load(); }, []);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return rows;
    return rows.filter(r => `${r.report_number||''} ${r.client_name||''} ${r.submitted_by_name||''}`.toLowerCase().includes(q));
  }, [rows, search]);

  const restore = async (r) => {
    const ok = await confirmModal({
      title: `Ripristinare il rapporto ${r.report_number}?`,
      message: `Tornerà visibile in Inbox e Spedisci con lo stato precedente al cestino.\n\nCliente: ${r.client_name||'—'} · Servizio del ${fromISO(r.service_date)}`,
      confirmLabel: 'Ripristina',
    });
    if (!ok) return;
    setBusyId(r.id);
    try {
      const c = await sb();
      const { error } = await c.rpc('restore_report', { p_token: currentAdmin.token, p_report_id: r.id });
      if (error) throw error;
      await logAudit(currentAdmin, 'restore', r, null);
      setRows(prev => prev.filter(x => x.id !== r.id));
      toast.success(`Rapporto ${r.report_number} ripristinato.`);
    } catch(e) { console.error(e); toast.error('Errore durante il ripristino.'); }
    setBusyId(null);
  };

  const hardDelete = async (r) => {
    const ok = await confirmModal({
      title: 'Eliminazione definitiva dal database',
      message: `Rapporto N° ${r.report_number}\nCliente: ${r.client_name||'—'}\nData: ${fromISO(r.service_date)}\n\nQuesta operazione è IRREVERSIBILE: il rapporto e tutta la sua cronologia saranno cancellati per sempre.\n\nDigita ELIMINA per confermare:`,
      confirmLabel: 'Elimina per sempre',
      danger: true,
      requireText: 'ELIMINA',
    });
    if (!ok) return;
    setBusyId(r.id);
    try {
      const c = await sb();
      await logAudit(currentAdmin, 'hard_delete', r, { service_date: r.service_date });
      const { error } = await c.rpc('hard_delete_report', { p_token: currentAdmin.token, p_report_id: r.id });
      if (error) throw error;
      setRows(prev => prev.filter(x => x.id !== r.id));
      toast.success(`Rapporto ${r.report_number} eliminato definitivamente.`);
    } catch(e) { console.error(e); toast.error('Errore.'); }
    setBusyId(null);
  };

  return (
    <div style={{padding:28,overflowY:'auto',height:'100vh',boxSizing:'border-box'}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:14}}>
        <div><div style={{fontWeight:600,fontSize:T.f.h,display:'flex',alignItems:'center',gap:9,color:T.c.text}}><I.trash size={18} /> Cestino</div><div style={{fontSize:T.f.md,color:T.c.textMuted,marginTop:4}}>Rapporti eliminati · {rows.length} totali · ripristinabili</div></div>
        <button onClick={load} style={{padding:'7px 12px',border:'1px solid #ddd',borderRadius:7,background:'#fff',cursor:'pointer',fontSize:12,fontFamily:'inherit'}}>⟳ Aggiorna</button>
      </div>
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Cerca N°, cliente o agente…" style={{width:'100%',padding:'10px 13px',border:'1px solid #ddd',borderRadius:9,fontSize:14,marginBottom:14,boxSizing:'border-box',fontFamily:'inherit'}} />
      {loading && <div style={{textAlign:'center',color:'#888',padding:30}}>Caricamento…</div>}
      {!loading && filtered.length===0 && (
        <div style={{textAlign:'center',color:'#aaa',padding:30,background:'#fafafa',borderRadius:10,border:'1px solid #eee'}}>
          {rows.length===0?'Cestino vuoto 🎉':'Nessun risultato per la ricerca.'}
        </div>
      )}
      <div style={{background:'#fff',borderRadius:12,border:'0.5px solid #e0e0e0',overflow:'hidden'}}>
        {filtered.map((r,i) => (
          <div key={r.id} style={{padding:'12px 16px',borderTop:i>0?'0.5px solid #f0f0f0':'none',display:'flex',alignItems:'center',gap:12}}>
            <div style={{flex:1,minWidth:0}}>
              <div style={{fontSize:13,fontWeight:500}}>{r.report_number} <span style={{color:'#888',fontWeight:400}}>· {r.client_name||'—'}</span></div>
              <div style={{fontSize:11,color:'#888',marginTop:2}}>Servizio {fromISO(r.service_date)} · da {r.submitted_by_name||'—'}</div>
              <div style={{fontSize:11,color:'#a32d2d',marginTop:2}}>Eliminato {fmtDT(r.deleted_at)}{r.deleted_by_admin_name?` da ${r.deleted_by_admin_name}`:''}</div>
            </div>
            <button onClick={() => restore(r)} disabled={busyId===r.id} style={{padding:'7px 14px',border:'1px solid #ccebc5',borderRadius:8,background:'#fff',cursor:'pointer',fontSize:12,color:GREEN,fontFamily:'inherit',fontWeight:500,opacity:busyId===r.id?0.5:1}}>↩ Ripristina</button>
            <button onClick={() => hardDelete(r)} disabled={busyId===r.id} style={{padding:'7px 14px',border:'1px solid #f0c8c8',borderRadius:8,background:'#fff',color:'#a32d2d',cursor:'pointer',fontSize:12,fontFamily:'inherit',opacity:busyId===r.id?0.5:1}}>🗑 Elimina definitivamente</button>
          </div>
        ))}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// TAB: REGOLAMENTO
// ═══════════════════════════════════════════════════════════════════
function RegolamentoTab() {
  const alertModal = useAlertModal();
  const confirmModal = useConfirm();
  const [content, setContent] = useState('');
  const [version, setVersion] = useState(1);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    sb().then(c => c.from('report_regulations').select('*').order('version',{ascending:false}).limit(1).single()).then(({data}) => {
      if (data) { setContent(data.content); setVersion(data.version); }
    });
  }, []);

  const save = async () => {
    const ok = await confirmModal({
      title: `Salvare come versione v${version+1}?`,
      message: 'Crei una nuova versione del regolamento. Per forzare la riaccettazione a tutti i collaboratori dovrai aggiornare REGULATION_VERSION nell\'app collaboratore.',
      confirmLabel: 'Salva nuova versione',
      tone: 'warning',
    });
    if (!ok) return;
    setSaving(true);
    const c = await sb();
    await c.from('report_regulations').insert({content,version:version+1,updated_by:'Admin',updated_at:new Date().toISOString()});
    setVersion(v => v+1);
    setSaved(true); setTimeout(() => setSaved(false), 3000);
    setSaving(false);
    await alertModal({
      title: `Regolamento salvato come v${version+1}`,
      message: `Per forzare la riaccettazione, aggiorna REGULATION_VERSION=${version+1} nel codice dell'app collaboratore.`,
      tone: 'success',
    });
  };

  return (
    <div style={{padding:28,maxWidth:700,height:'100vh',boxSizing:'border-box',display:'flex',flexDirection:'column'}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6}}>
        <div><div style={{fontWeight:600,fontSize:T.f.h,display:'flex',alignItems:'center',gap:9,color:T.c.text}}><I.fileText size={18} /> Regolamento</div><div style={{fontSize:T.f.md,color:T.c.textMuted,marginTop:4}}>Versione corrente: v{version}</div></div>
        <button onClick={save} disabled={saving} style={{padding:'9px 20px',background:GREEN,color:'#fff',border:'none',borderRadius:9,cursor:'pointer',fontSize:13,fontWeight:500,fontFamily:'inherit'}}>
          {saving?'Salvataggio…':saved?'✓ Salvato':'Salva nuova versione'}
        </button>
      </div>
      <div style={{fontSize:12,color:'#e07000',background:'#faeeda',padding:'9px 13px',borderRadius:8,marginBottom:14}}>
        ⚠️ Salvando crei una nuova versione. Per forzare la riaccettazione aggiorna <code>REGULATION_VERSION</code> nell'app collaboratore.
      </div>
      <textarea value={content} onChange={e=>setContent(e.target.value)} style={{flex:1,padding:'14px 16px',border:'1px solid #ddd',borderRadius:10,fontSize:13,lineHeight:1.7,resize:'none',fontFamily:'inherit',boxSizing:'border-box',outline:'none'}} />
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════
// APP ROOT
// ═══════════════════════════════════════════════════════════════════
export default function App() {
  const alertModal = useAlertModal();
  const [currentAdmin, setCurrentAdmin] = useState(() => {
    try {
      const s = JSON.parse(localStorage.getItem(ADMIN_SESSION_KEY));
      if (!s || !s.id || !s.admin_name || !s.token) return null;
      if (s.savedAt && Date.now() - s.savedAt > ADMIN_SESSION_DAYS * 24 * 60 * 60 * 1000) {
        localStorage.removeItem(ADMIN_SESSION_KEY);
        return null;
      }
      return { id: s.id, admin_name: s.admin_name, is_super: !!s.is_super, token: s.token };
    } catch {}
    return null;
  });
  const [activeTab, setActiveTab] = useState('inbox');

  const handleLogin = (admin) => {
    localStorage.setItem(ADMIN_SESSION_KEY, JSON.stringify({
      id: admin.id, admin_name: admin.admin_name, is_super: !!admin.is_super, token: admin.token, savedAt: Date.now()
    }));
    setCurrentAdmin({ id: admin.id, admin_name: admin.admin_name, is_super: !!admin.is_super, token: admin.token });
  };
  const handleLogout = async () => {
    try {
      if (currentAdmin?.token) {
        const c = await sb();
        await c.rpc('logout_session', { p_token: currentAdmin.token });
      }
    } catch {}
    localStorage.removeItem(ADMIN_SESSION_KEY);
    setCurrentAdmin(null);
    setActiveTab('inbox');
  };

  // Realtime presence: track this admin in a shared channel; expose online list to children
  const [onlineAdmins, setOnlineAdmins] = useState({});
  useEffect(() => {
    if (!currentAdmin?.id) return;
    let channel;
    let cancelled = false;
    (async () => {
      const c = await sb();
      if (cancelled) return;
      channel = c.channel('admin-presence', { config: { presence: { key: currentAdmin.id } } });
      channel.on('presence', { event: 'sync' }, () => {
        const state = channel.presenceState();
        const flat = {};
        Object.entries(state).forEach(([id, metas]) => {
          flat[id] = (metas && metas[0]) ? metas[0] : { admin_name: '?' };
        });
        setOnlineAdmins(flat);
      });
      channel.subscribe(async (status) => {
        if (status === 'SUBSCRIBED') {
          await channel.track({ admin_id: currentAdmin.id, admin_name: currentAdmin.admin_name, is_super: !!currentAdmin.is_super, online_at: new Date().toISOString() });
        }
      });
    })();
    return () => {
      cancelled = true;
      if (channel) channel.unsubscribe();
    };
  }, [currentAdmin?.id]);

  // Periodic + on-focus session validation: if invalidated server-side, force re-login
  useEffect(() => {
    if (!currentAdmin?.token) return;
    let cancelled = false;
    const check = async () => {
      try {
        const c = await sb();
        const { data, error } = await c.rpc('validate_session', { p_token: currentAdmin.token });
        if (cancelled) return;
        if (error) return;
        if (!data || data.length === 0) {
          localStorage.removeItem(ADMIN_SESSION_KEY);
          setCurrentAdmin(null);
          alertModal({ title: 'Sessione terminata', message: 'Per motivi di sicurezza la tua sessione è stata invalidata. Effettua di nuovo l\'accesso.', tone: 'warning' });
        } else {
          const fresh = data[0];
          if (fresh.is_super !== currentAdmin.is_super) {
            const updated = { ...currentAdmin, is_super: !!fresh.is_super };
            setCurrentAdmin(updated);
            const stored = JSON.parse(localStorage.getItem(ADMIN_SESSION_KEY) || '{}');
            localStorage.setItem(ADMIN_SESSION_KEY, JSON.stringify({ ...stored, is_super: !!fresh.is_super }));
          }
        }
      } catch {}
    };
    check();
    const id = setInterval(() => { if (!document.hidden) check(); }, 60000);
    const onFocus = () => check();
    window.addEventListener('focus', onFocus);
    return () => { cancelled = true; clearInterval(id); window.removeEventListener('focus', onFocus); };
  }, [currentAdmin?.token]);

  if (!currentAdmin) return <AdminLogin onLogin={handleLogin} />;

  const isSuper = !!currentAdmin.is_super;
  const allowedTab = (tab) => {
    const item = NAV_ALL.find(i => i.id === tab);
    return item && (!item.super || isSuper);
  };
  const safeTab = allowedTab(activeTab) ? activeTab : 'inbox';

  return (
    <div style={{display:'flex',height:'100vh',overflow:'hidden',fontFamily:'-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'}}>
      <Sidebar active={safeTab} onNav={setActiveTab} onLogout={handleLogout} adminName={currentAdmin.admin_name} isSuper={isSuper} />
      <div style={{flex:1,overflow:'hidden'}}>
        {safeTab==='inbox'           && <InboxTab currentAdmin={currentAdmin} />}
        {safeTab==='spedisci'        && <SpedisciTab currentAdmin={currentAdmin} />}
        {safeTab==='clienti'         && <ClientiTab />}
        {safeTab==='collaboratori'   && isSuper && <CollaboratoriTab currentAdmin={currentAdmin} />}
        {safeTab==='amministratori'  && isSuper && <AmministratoriTab currentAdmin={currentAdmin} onlineAdmins={onlineAdmins} />}
        {safeTab==='cronologia'      && isSuper && <CronologiaTab />}
        {safeTab==='cestino'         && isSuper && <CestinoTab currentAdmin={currentAdmin} />}
        {safeTab==='regolamento'     && isSuper && <RegolamentoTab />}
      </div>
    </div>
  );
}
